package com.projectnuke.fusion.retrieval

// Deterministic document status policy. Never generated by a model, never a
// hidden token call: it maps typed parser/index metadata to human Korean
// copy. Implementation jargon (SandboxedPdfLoader, sidecar cache, semantic
// rankers) never reaches users.

object DocumentStatusPolicy {

    /** Product-friendly rejection copy for a typed status. */
    fun statusMessage(status: DocumentExtractionStatus): String = when (status) {
        DocumentExtractionStatus.READY ->
            "이 문서의 텍스트를 사용할 수 있어요."
        DocumentExtractionStatus.NO_TEXT_LAYER ->
            "이 PDF에서는 읽을 수 있는 텍스트를 찾지 못했습니다."
        DocumentExtractionStatus.IMAGE_ONLY_NO_OCR ->
            "이 PDF는 스캔 이미지로 되어 있어 현재 텍스트를 읽을 수 없습니다."
        DocumentExtractionStatus.PASSWORD_PROTECTED ->
            "암호가 걸린 PDF는 아직 읽을 수 없습니다."
        DocumentExtractionStatus.TOO_MANY_PAGES ->
            "이 PDF는 현재 지원하는 페이지 수를 초과했습니다."
        DocumentExtractionStatus.TOO_MUCH_TEXT ->
            "이 PDF의 텍스트가 현재 문서 처리 한도를 초과했습니다."
        DocumentExtractionStatus.TOO_LARGE_FILE ->
            "이 PDF 파일이 너무 커서 처리할 수 없습니다."
        DocumentExtractionStatus.UNREADABLE ->
            "이 PDF를 읽지 못했습니다. 손상되었거나 지원하지 않는 파일일 수 있어요."
        DocumentExtractionStatus.UNSUPPORTED ->
            "지원하지 않는 문서 형식이에요."
    }

    /** Human summary of an extracted document. Never chunk/ranker jargon. */
    fun documentSummary(document: ExtractedLocalDocument): String = when {
        !document.isPdf -> "텍스트 사용 가능"
        document.totalExtractedChars <= 0 -> "텍스트 없음"
        document.textPageCount >= document.pageCount ->
            "PDF · ${document.pageCount}쪽 · 텍스트 사용 가능"
        document.textPageCount == 0 ->
            "PDF · 스캔 이미지 · OCR 필요"
        else ->
            "${document.pageCount}쪽 중 ${document.textPageCount}쪽의 텍스트를 사용할 수 있어요."
    }

    /** True when an indexed PDF has no usable text at all. */
    fun requiresOcr(status: DocumentExtractionStatus?): Boolean =
        status == DocumentExtractionStatus.IMAGE_ONLY_NO_OCR

    /** 1-based product page label. */
    fun pageLabel(pageNumber: Int): String = "${pageNumber}쪽"

    /** Bounded page-and-file provenance label. */
    fun pageProvenanceLabel(displayName: String, pageNumber: Int): String =
        "${displayName} · ${pageLabel(pageNumber)}"

    /**
     * Conversation file inventory states (F4). Returns null when the status
     * is unknown so callers can fall back to MIME display without lying.
     */
    fun inventoryPdfLabel(status: DocumentExtractionStatus?): String? = when (status) {
        null -> null
        DocumentExtractionStatus.READY, DocumentExtractionStatus.NO_TEXT_LAYER -> "PDF · 사용할 수 없음"
        DocumentExtractionStatus.IMAGE_ONLY_NO_OCR -> "PDF · 스캔 이미지 · OCR 필요"
        DocumentExtractionStatus.PASSWORD_PROTECTED -> "PDF · 암호화됨"
        else -> "PDF · 사용할 수 없음"
    }

    /** Inventory label enriched with page counts when the index knows them. */
    fun inventoryPdfLabel(document: ExtractedLocalDocument): String = when {
        document.pageCount <= 0 -> "PDF · 사용할 수 없음"
        document.textPageCount >= document.pageCount -> "PDF · ${document.pageCount}쪽 · 텍스트 사용 가능"
        document.textPageCount == 0 -> "PDF · 스캔 이미지 · OCR 필요"
        document.imageOnlyPageCount > 0 -> "PDF · ${document.pageCount}쪽 · 이미지 전용 ${document.imageOnlyPageCount}쪽"
        else -> "PDF · 텍스트 없음"
    }

    /** Same truthful inventory copy using metadata-only UI status. */
    fun inventoryPdfLabel(status: DocumentIndexStatusSnapshot): String = when {
        status.pageCount <= 0 -> "PDF · 사용할 수 없음"
        status.textPageCount >= status.pageCount ->
            "PDF · ${status.pageCount}쪽 · 텍스트 사용 가능"
        status.textPageCount == 0 -> "PDF · 스캔 이미지 · OCR 필요"
        status.imageOnlyPageCount > 0 ->
            "PDF · ${status.pageCount}쪽 · 이미지 전용 ${status.imageOnlyPageCount}쪽"
        else -> "PDF · 텍스트 없음"
    }
}
